    16	const WIN_CACHE_TTL: Duration = Duration::from_millis(150);
    17	/// Cache stores an `Arc` so cache hits return via a cheap atomic ref-count
    18	/// increment instead of deep-cloning ~20 JSON values per call. With N pets
    19	/// each calling 33×/sec, this avoids thousands of short-lived allocations/sec.
    20	static WIN_CACHE: Mutex<Option<(Instant, Arc<Vec<serde_json::Value>>)>> = Mutex::new(None);
