    22	#[cfg(windows)]
    23	mod win {
    24	    use serde::Serialize;
    25	    use windows::Win32::Foundation::{BOOL, HWND, LPARAM, RECT, TRUE};
    26	    use windows::Win32::UI::WindowsAndMessaging::{
    27	        EnumWindows, GetWindowRect, GetWindowTextW, GetWindowThreadProcessId, IsWindowVisible,
    28	    };
    29	
    30	    #[derive(Serialize)]
    31	    pub struct SystemWindowInfo {
    32	        pub title: String,
    33	        pub x: i32,
    34	        pub y: i32,
    35	        pub width: i32,
    36	        pub height: i32,
    37	    }
