   568	#[cfg_attr(mobile, tauri::mobile_entry_point)]
   569	pub fn run() {
   570	    tauri::Builder::default()
   571	        // Must be the first plugin: a second launch (double-clicking the
   572	        // shortcut while the app runs) exits immediately and the running
   573	        // instance opens Settings instead , no duplicate pets.
   574	        .plugin(tauri_plugin_single_instance::init(|app, _argv, _cwd| {
   575	            open_settings_impl(app.clone());
   576	        }))
   577	        .plugin(tauri_plugin_autostart::init(
   578	            tauri_plugin_autostart::MacosLauncher::LaunchAgent,
   579	            None,
   580	        ))
   581	        .plugin(tauri_plugin_notification::init())
   582	        .plugin(tauri_plugin_updater::Builder::new().build())
   583	        .plugin(tauri_plugin_process::init())
   584	        .invoke_handler(tauri::generate_handler![
   585	            open_settings,
   586	            open_url,
   587	            sync_desktop_pet_windows,
   588	            set_lang,
   589	            set_desktop_pets_visible,
   590	            get_desktop_pets_visible,
   591	            open_popover,
   592	            log_debug,
   593	            set_hit_rect,
   594	            persist_floating_ball_position,
   595	            set_floating_ball_visible,
   596	            get_floating_ball_visible,
   597	            sys_windows::list_system_windows
   598	        ])
   599	        .setup(|app| {
   600	            app.manage(Mutex::new(HitRectMap::new()));
   601	            app.manage(Mutex::new(read_pet_positions()));
   602	            app.manage(Mutex::new(DesktopPetSyncState::default()));
   603	
   604	            // Background loop: make each persistent overlay click-through
   605	            // outside its opaque rectangle and persist every instance position.
   606	            let handle = app.handle().clone();
   607	            std::thread::spawn(move || {
   608	                let mut last_ignore: std::collections::HashMap<String, bool> = std::collections::HashMap::new();
   609	                let mut flip_logs: u32 = 0;
   610	                let mut last_saved = read_pet_positions();
   611	                let mut tick: u32 = 0;
   612	                loop {
   613	                    // 60ms (≈16Hz): click-through detection doesn't need 33Hz
   614	                    // polling. The cursor rarely traverses a pet's opaque rect
   615	                    // in <60ms, and halving the tick rate halves the Win32
   616	                    // GetCursorPos + GetWindowRect calls per second.
   617	                    std::thread::sleep(Duration::from_millis(60));
   618	
   619	                    // Single cursor read per tick (shared across all pet windows).
   620	                    let cur = handle.cursor_position();
   621	
   622	                    // Snapshot all pet windows once per tick so spawns/closes
   623	                    // during the loop don't corrupt the iterator.
   624	                    let wins: Vec<(String, tauri::WebviewWindow)> = handle
   625	                        .webview_windows()
   626	                        .into_iter()
   627	                        .filter(|(label, _)| is_pet_window(label))
   628	                        .collect();
   629	
   630	                    // Snapshot all hit rects in ONE lock acquisition (instead of
   631	                    // N locks per tick). The clone is ~12 entries × 32 bytes.
   632	                    let rects: HitRectMap = handle
   633	                        .try_state::<Mutex<HitRectMap>>()
   634	                        .and_then(|s| s.lock().ok().map(|m| m.clone()))
   635	                        .unwrap_or_default();
   636	
   637	                    for (label, win) in &wins {
   638	                        let Ok(wp) = win.outer_position() else { continue };
   639	                        // Fail-safe: no rect yet (webview still booting) or
   640	                        // cursor unreadable → keep INTERACTIVE.
   641	                        let inside = match &cur {
   642	                            Ok(cur) => match rects.get(label) {
   643	                                Some(r) if r.w > 0.0 => {
   644	                                    let rx = cur.x - wp.x as f64;
   645	                                    let ry = cur.y - wp.y as f64;
   646	                                    rx >= r.x && rx <= r.x + r.w && ry >= r.y && ry <= r.y + r.h
   647	                                }
   648	                                _ => true, // no rect yet → stay interactive
   649	                            },
   650	                            Err(_) => true,
   651	                        };
   652	                        // ignore_cursor_events = true → clicks pass through.
   653	                        let ignore = !inside;
   654	                        if last_ignore.get(label) != Some(&ignore) {
   655	                            let _ = win.set_ignore_cursor_events(ignore);
   656	                            last_ignore.insert(label.clone(), ignore);
   657	                            if flip_logs < 60 {
   658	                                flip_logs += 1;
   659	                                let cur_str = cur.as_ref().map_or("err".to_string(), |c| format!("({:.0},{:.0})", c.x, c.y));
   660	                                dlog(&format!(
   661	                                    "hit flip: label={label} ignore={ignore} cur={cur_str} win=({},{})",
   662	                                    wp.x, wp.y
   663	                                ));
   664	                            }
   665	                        }
   666	                    }
   667	
   668	                    // Prune closed windows and persist every instance position,
   669	                    // both throttled to roughly once per second.
   670	                    tick = tick.wrapping_add(1);
   671	                    if tick % 17 == 0 {
   672	                        let active: std::collections::HashSet<&String> =
   673	                            wins.iter().map(|(label, _)| label).collect();
   674	                        if let Some(state) = handle.try_state::<Mutex<HitRectMap>>() {
   675	                            if let Ok(mut rects) = state.lock() {
   676	                                rects.retain(|label, _| active.contains(label));
   677	                            }
   678	                        }
   679	                        last_ignore.retain(|label, _| active.contains(label));
   680	
   681	                        let mut changed = false;
   682	                        for (label, window) in &wins {
   683	                            let Some(id) = label.strip_prefix(PET_WINDOW_PREFIX) else { continue };
   684	                            let Ok(position) = window.outer_position() else { continue };
   685	                            let next = (position.x, position.y);
   686	                            if last_saved.get(id) != Some(&next) {
   687	                                last_saved.insert(id.to_owned(), next);
   688	                                changed = true;
   689	                            }
   690	                        }
   691	                        if changed {
   692	                            if let Some(state) = handle.try_state::<Mutex<PetPositionMap>>() {
   693	                                if let Ok(mut positions) = state.lock() {
   694	                                    *positions = last_saved.clone();
   695	                                    write_pet_positions(&positions);
   696	                                }
   697	                            }
   698	                        }
   699	                    }
   700	                }
   701	            });
   702	
   703	            // Tray menu , the pet window is frameless, so this is how you reach
   704	            // Settings or quit the app. Labels start in the saved language; the
   705	            // Settings switcher re-labels them live via the `set_lang` command.
   706	            let (p_lbl, s_lbl, q_lbl) = tray_labels(&read_lang());
   707	            let pets_visible = read_desktop_pets_visible();
   708	            let show_pet_i = tauri::menu::CheckMenuItem::with_id(
   709	                app, "show_pet", p_lbl, true, pets_visible, None::<&str>)?;
   710	            let settings_i = MenuItem::with_id(app, "settings", s_lbl, true, None::<&str>)?;
   711	            let quit_i = MenuItem::with_id(app, "quit", q_lbl, true, None::<&str>)?;
   712	            let menu = Menu::with_items(app, &[&show_pet_i, &settings_i, &quit_i])?;
   713	            let mut tray = TrayIconBuilder::new()
   714	                .tooltip("DesktopPet")
   715	                .menu(&menu)
   716	                .show_menu_on_left_click(false)
   717	                .on_tray_icon_event(|tray, event| {
   718	                    // Left-click on the tray icon opens Settings; the pet's
   719	                    // right-click popover covers the quick controls.
   720	                    if let tauri::tray::TrayIconEvent::Click {
   721	                        button: tauri::tray::MouseButton::Left,
   722	                        button_state: tauri::tray::MouseButtonState::Up,
   723	                        ..
   724	                    } = event
   725	                    {
   726	                        open_settings_impl(tray.app_handle().clone());
   727	                    }
   728	                })
   729	                .on_menu_event(|app, event| match event.id.as_ref() {
   730	                    "show_pet" => set_desktop_pets_visible(app.clone(), !read_desktop_pets_visible()),
   731	                    "settings" => open_settings_impl(app.clone()),
   732	                    "quit" => app.exit(0),
   733	                    _ => {}
   734	                });
   735	            if let Some(icon) = app.default_window_icon() {
   736	                tray = tray.icon(icon.clone());
   737	            }
   738	            let tray = tray.build(app)?;
   739	            app.manage(Mutex::new(TrayItems {
   740	                show_pet: show_pet_i.clone(),
   741	                settings: settings_i.clone(),
   742	                quit: quit_i.clone(),
   743	                tray,
   744	            }));
   745	            dlog("setup complete, tray + loop running");
   746	            // First run: open Settings so the user knows to pick a pet
   747	            // (otherwise the pet just sits there silently).
   748	            let marker = dirs::config_dir().map(|d| d.join("DesktopPet").join(".onboarded"));
   749	            if let Some(m) = marker {
   750	                if !m.exists() {
   751	                    // Call the sync impl directly: open_settings is an async fn
   752	                    // (Tauri command), so calling it without .await would create
   753	                    // a Future that's never polled and do nothing.
   754	                    open_settings_impl(app.handle().clone());
   755	                    if let Some(parent) = m.parent() {
   756	                        let _ = std::fs::create_dir_all(parent);
   757	                    }
   758	                    let _ = std::fs::write(&m, "1");
   759	                }
   760	            }
   761	
   762	            // Floating ball: a stable click target that doesn't run away with
   763	            // the pet. Hidden by config (applies on next launch); spawned in a
   764	            // worker thread because window creation must not run on the event
   765	            // loop on Windows (same reason as open_settings_impl).
   766	            if read_ball_visible() {
   767	                let app2 = app.handle().clone();
   768	                std::thread::spawn(move || spawn_floating_ball_impl(app2));
   769	            }
   770	            Ok(())
   771	        })
   772	        .run(tauri::generate_context!())
   773	        .expect("error while running DesktopPet");
   774	}
     1	// Windows-only: enumerate visible top-level windows so the pet can climb
     2	// their edges. On other platforms the command returns an empty list.
     3	//
     4	// We use the `windows` crate (microsoft/windows-rs) with Win32
     5	// EnumWindows + IsWindowVisible + GetWindowRect + GetWindowTextW.
     6	//
     7	// A short-lived TTL cache sits in front of the enumeration: the roam engine
     8	// ticks every 30ms per pet window, and without the cache N pets would fire
     9	// N×33 EnumWindows calls per second. The cache returns the previous snapshot
    10	// for 150ms, capping the real enumeration at ~7 calls/sec regardless of how
    11	// many pets are roaming.
    12	
    13	use std::sync::{Arc, Mutex};
    14	use std::time::{Duration, Instant};
    15	
    16	const WIN_CACHE_TTL: Duration = Duration::from_millis(150);
    17	/// Cache stores an `Arc` so cache hits return via a cheap atomic ref-count
    18	/// increment instead of deep-cloning ~20 JSON values per call. With N pets
    19	/// each calling 33×/sec, this avoids thousands of short-lived allocations/sec.
    20	static WIN_CACHE: Mutex<Option<(Instant, Arc<Vec<serde_json::Value>>)>> = Mutex::new(None);
    21	
    22	#[cfg(windows)]
    23	mod win {
    24	    use serde::Serialize;
    25	    use windows::Win32::Foundation::{BOOL, HWND, LPARAM, RECT, TRUE};
    26	    use windows::Win32::UI::WindowsAndMessaging::{
    27	        EnumWindows, GetWindowRect, GetWindowTextW, GetWindowThreadProcessId, IsWindowVisible,
    28	    };
    29	
    30	    #[derive(Serialize)]
    31	    pub struct SystemWindowInfo {
    32	        pub title: String,
    33	        pub x: i32,
