    10	/// Tray menu items kept around so the language switcher can re-label them live.
    11	#[allow(dead_code)] // `tray` is held so the icon stays alive for the app's lifetime
    12	struct TrayItems {
    13	    show_pet: tauri::menu::CheckMenuItem<tauri::Wry>,
    14	    settings: MenuItem<tauri::Wry>,
    15	    quit: MenuItem<tauri::Wry>,
    16	    tray: tauri::tray::TrayIcon<tauri::Wry>,
    17	}
    18	
    19	/// The pet's opaque region in physical pixels, relative to the window's top-left.
    20	/// The frontend reports this (canvas + visible bubble) so the background thread
    21	/// can make the transparent rest of the window click-through.
    22	#[derive(Default, Clone)]
    23	#[cfg_attr(not(windows), allow(dead_code))]
    24	struct HitRect {
    25	    x: f64,
    26	    y: f64,
    27	    w: f64,
    28	    h: f64,
    29	}
    30	
    31	/// Per-window hit rects: every persistent desktop-pet window reports its own
    32	/// opaque rect so the click-through loop can handle them independently.
    33	type HitRectMap = std::collections::HashMap<String, HitRect>;
    34	
    35	const PET_WINDOW_PREFIX: &str = "pet-";
    36	const MAX_DESKTOP_PETS: usize = 12;
    37	type PetPositionMap = std::collections::HashMap<String, (i32, i32)>;
    38	
    39	#[derive(Default)]
    40	struct DesktopPetSyncState {
    41	    generation: u64,
    42	}
    43	
    44	#[derive(Clone, Deserialize)]
    45	#[serde(rename_all = "camelCase")]
    46	struct DesktopPetWindow {
    47	    id: String,
    48	    visible: bool,
    49	}
    50	
    51	fn is_pet_window(label: &str) -> bool {
    52	    label.starts_with(PET_WINDOW_PREFIX)
    53	}
    54	
    55	fn pet_window_label(id: &str) -> String {
    56	    format!("{PET_WINDOW_PREFIX}{id}")
    57	}
    58	
    59	fn valid_pet_id(id: &str) -> bool {
    60	    !id.is_empty()
    61	        && id.len() <= 64
    62	        && id.chars().all(|c| c.is_ascii_lowercase() || c.is_ascii_digit() || c == '-')
    63	}
    64	
    65	fn pet_positions_file() -> Option<std::path::PathBuf> {
    66	    dirs::config_dir().map(|d| d.join("DesktopPet").join("pet-positions.json"))
    67	}
    68	
    69	fn read_pet_positions() -> PetPositionMap {
    70	    let Some(path) = pet_positions_file() else { return PetPositionMap::new() };
    71	    let Ok(raw) = std::fs::read_to_string(path) else { return PetPositionMap::new() };
    72	    serde_json::from_str(&raw).unwrap_or_default()
    73	}
