    39	    /// Collect visible top-level windows with a non-empty title and a
    40	    /// reasonable size (>40x40). Excludes the pet's own process windows so
    41	    /// the pet doesn't try to climb itself.
    42	    pub fn enumerate() -> Vec<SystemWindowInfo> {
    43	        let mut result: Vec<SystemWindowInfo> = Vec::new();
    44	        let ptr = &mut result as *mut Vec<SystemWindowInfo> as isize;
    45	        // SAFETY: EnumWindows calls our callback synchronously. The callback
    46	        // only touches the Vec through the raw pointer we pass as LPARAM.
    47	        unsafe {
    48	            let _ = EnumWindows(Some(enum_proc), LPARAM(ptr));
    49	        }
    50	        result
    51	    }
    52	
    53	    extern "system" fn enum_proc(hwnd: HWND, lparam: LPARAM) -> BOOL {
    54	        unsafe {
    55	            if !IsWindowVisible(hwnd).as_bool() {
    56	                return TRUE;
    57	            }
    58	
    59	            // Skip zero-size / minimized windows.
    60	            let mut rect = RECT::default();
    61	            if GetWindowRect(hwnd, &mut rect).is_err() {
    62	                return TRUE;
    63	            }
    64	            let w = rect.right - rect.left;
    65	            let h = rect.bottom - rect.top;
    66	            if w < 40 || h < 40 {
    67	                return TRUE;
    68	            }
    69	
    70	            // Exclude the pet's own process windows so it doesn't climb itself.
    71	            let mut pid: u32 = 0;
    72	            GetWindowThreadProcessId(hwnd, Some(&mut pid));
    73	            if pid == std::process::id() {
    74	                return TRUE;
    75	            }
    76	
    77	            // Only keep windows with a non-empty title (filters out
    78	            // tooltips, IME bars, and other shell chrome).
    79	            let mut buf = [0u16; 512];
    80	            let len = GetWindowTextW(hwnd, &mut buf);
    81	            if len == 0 {
    82	                return TRUE;
    83	            }
    84	            let title = String::from_utf16_lossy(&buf[..len as usize]);
    85	
    86	            let vec = &mut *(lparam.0 as *mut Vec<SystemWindowInfo>);
    87	            vec.push(SystemWindowInfo {
    88	                title,
    89	                x: rect.left,
    90	                y: rect.top,
    91	                width: w,
    92	                height: h,
    93	            });
    94	        }
    95	        TRUE
    96	    }
    97	}
