   103	/// instead of deep-cloning every JSON value on every call.
   104	#[tauri::command]
   105	pub fn list_system_windows() -> Arc<Vec<serde_json::Value>> {
   106	    // Fast path: return the cached snapshot if it's still fresh.
   107	    if let Ok(guard) = WIN_CACHE.lock() {
   108	        if let Some((ts, ref data)) = *guard {
   109	            if ts.elapsed() < WIN_CACHE_TTL {
   110	                return Arc::clone(data);
   111	            }
   112	        }
