   117	        win::enumerate()
   118	            .into_iter()
   119	            .map(|w| serde_json::json!({
   120	                "title": w.title,
   121	                "x": w.x,
   122	                "y": w.y,
   123	                "width": w.width,
   124	                "height": w.height,
   125	            }))
