103	  const cfg = loadConfig();
104	  if (!cfg.enabled || cfg.mode === "stay") {
105	    handleStationary();
106	    return false;
107	  }
108	
109	  wake();
110	  const moved = await stepMode(cfg.mode);
111	  if (!moved && mood === "idle" && Date.now() - lastMoveTs > SLEEP_AFTER_MS) {
112	    enterSleep();
113	  }
114	  return moved;
