392	// Draws frame 0 (first column of the Idle row) of an 8x9 spritesheet as a preview.
393	function drawThumb(cv: HTMLCanvasElement, url: string) {
394	  const ctx = cv.getContext("2d");
395	  if (!ctx) return;
396	  ctx.imageSmoothingEnabled = false;
397	  const img = new Image();
398	  img.onload = () => {
399	    const fw = img.naturalWidth / 8, fh = img.naturalHeight / 9;
400	    if (!fw || !fh) return;
401	    const sc = Math.min(cv.width / fw, cv.height / fh);
402	    const dw = fw * sc, dh = fh * sc;
