559	/// Community manifest first, Petdex library shuffled after, deduped by slug.
560	async function loadBrowseSources(): Promise<RemotePet[]> {
561	  const norm = (p: any, community: boolean): RemotePet | null => {
562	    if (!p?.slug || !p?.spritesheetUrl) return null;
563	    const author = (p.submittedBy || "").trim() || "community";
564	    return { slug: p.slug, name: p.displayName ?? p.slug, url: p.spritesheetUrl,
565	      petJsonUrl: p.petJsonUrl, kind: p.kind ?? "creature", author, community };
566	  };
567	  const fetchList = async (url: string, community: boolean): Promise<RemotePet[]> => {
568	    try {
569	      const j: any = await (await fetch(url)).json();
570	      return (j.pets ?? []).map((p: any) => norm(p, community)).filter(Boolean);
571	    } catch { return []; }
572	  };
573	  const [community, library] = await Promise.all([
574	    fetchList("https://agentpet.thenightwatcher.online/api/pets", true),
575	    fetchList("https://pets.thenightwatcher.online/manifest.json", false),
576	  ]);
577	  for (let i = library.length - 1; i > 0; i--) { // shuffle like macOS
578	    const j = Math.floor(Math.random() * (i + 1));
579	    [library[i], library[j]] = [library[j], library[i]];
580	  }
581	  const seen = new Set<string>();
582	  return [...community, ...library].filter((p) => seen.has(p.slug) ? false : (seen.add(p.slug), true));
583	}
