879	      if (Array.isArray(v) && v.length) return v.filter((x) => Number.isFinite(x) && x >= 0).map((x) => Number(x));
880	    } catch {}
881	    return clips.length ? [boundClip("idle")] : [];
882	  };
883	  const saveIdleClips = (vals: number[]) => {
884	    const clean = vals.filter((x) => Number.isFinite(x) && x >= 0).map((x) => Number(x));
885	    localStorage.setItem(IDLE_CLIPS_KEY, JSON.stringify(clean));
886	    emit("bubble-changed", null);
887	  };
888	  const readIdleMode = () => localStorage.getItem(IDLE_MODE_KEY) || "random";
889	  const readIdleInterval = () => {
890	    const n = Number.parseFloat(localStorage.getItem(IDLE_INTERVAL_KEY) ?? "");
891	    return Number.isFinite(n) && n >= 1 ? n : DEFAULT_IDLE_INTERVAL;
892	  };
893	
894	  const drawFrame = (cv: HTMLCanvasElement, clip: Rect[], frame: number) => {
895	    const ctx = cv.getContext("2d");
896	    if (!ctx || !img || !clip.length) return;
897	    const r = clip[frame % clip.length];
898	    const maxW = Math.max(...clip.map((x) => x.w));
899	    const sc = Math.min(cv.width / maxW, cv.height / r.h);
900	    const dw = r.w * sc, dh = r.h * sc;
901	    ctx.imageSmoothingEnabled = false;
902	    ctx.clearRect(0, 0, cv.width, cv.height);
903	    ctx.drawImage(img, r.x, r.y, r.w, r.h, (cv.width - dw) / 2, cv.height - dh, dw, dh);
904	  };
905	
906	  const paint = () => {
907	    grid.innerHTML = "";
908	    if (!clips.length) { idleWrap.style.display = "none"; return; }
909	
910	    const isIdle = mood === "idle";
911	    const idleSelected = new Set(readIdleClips());
912	    const currentBinding = boundClip(mood);
913	
914	    clips.forEach((clip, i) => {
915	      const cell = document.createElement("button");
916	      const selected = isIdle ? idleSelected.has(i) : i === currentBinding;
917	      cell.className = "anim-cell" + (selected ? " sel" : "");
918	      const cv = document.createElement("canvas");
919	      cv.width = 54; cv.height = 44;
920	      drawFrame(cv, clip, 0);
921	      const label = document.createElement("span");
922	      label.className = "cap";
923	      label.textContent = `${t("Clip")} ${i + 1}`;
924	      cell.appendChild(cv);
925	      cell.appendChild(label);
926	      cell.onclick = () => {
927	        if (isIdle) {
928	          // Multi-select playlist; never leave it empty.
929	          if (idleSelected.has(i) && idleSelected.size <= 1) return;
930	          if (idleSelected.has(i)) idleSelected.delete(i);
 73	/// One engine tick. Priority: throw > drag-sample > drag-release > mood-pause > sleep > mode.
 74	/// Returns true when the pet is actively moving/interacting and needs the fast
 75	/// (30ms) tick; false when resting/sleeping/stationary so the loop can use the
 76	/// idle (200ms) tick and skip most IPC calls.
 77	async function tick(): Promise<boolean> {
 78	  if (isThrowing()) return true;
 79	  if (dragging) {
 80	    const pos = await currentLogicalPos();
 81	    if (pos) recordSample(pos);
 82	    return true;
 83	  }
 84	  if (releasePending) {
 85	    releasePending = false;
 86	    const vel = releaseVelocity();
 87	    clearSamples();
 88	    if (vel && Math.hypot(vel.vx, vel.vy) > THROW_MIN_SPEED) {
 89	      wake();
 90	      await handleDragRelease(vel);
 91	      return true;
 92	    }
 93	  }
 94	
 95	  // Mood-driven freeze: keep the pet still while the user needs to see the
 96	  // bubble or the celebrate burst. Throws and drags above still work.
 97	  if (MOOD_PAUSES_ROAM.has(mood)) {
 98	    wake();
 99	    petRef?.clearRow();
100	    return false;
101	  }
102	
103	  const cfg = loadConfig();
104	  if (!cfg.enabled || cfg.mode === "stay") {
105	    handleStationary();
106	    return false;
107	  }
108	
109	  wake();
110	  const moved = await stepMode(cfg.mode);
111	  if (!moved && mood === "idle" && Date.now() - lastMoveTs > SLEEP_AFTER_MS) {
112	    enterSleep();
113	  }
114	  return moved;
115	}
116	
117	/// Run one mode step and apply it. Returns true if the pet actually moved.
118	async function stepMode(mode: RoamMode): Promise<boolean> {
119	  const env = await fetchEnvironment();
120	  if (!env) return false;
121	  const pos = await currentLogicalPos();
122	  if (!pos) return false;
123	
124	  const next = await runMode(mode, { env, pos, pet: petRef });
125	  const clamped = clampToBounds(next, env.workArea);
126	  if (Math.abs(clamped.x - pos.x) < 0.5 && Math.abs(clamped.y - pos.y) < 0.5) {
127	    return false;
128	  }
129	  lastMoveTs = Date.now();
130	  try { await setLogical(clamped); }
131	  catch (e) { void invoke("log_debug", { msg: `roam: setPosition error: ${e}` }).catch(() => {}); }
132	  return true;
133	}
134	
135	/// Pet is stationary (mode is stay or roaming disabled): maybe doze off.
136	function handleStationary(): void {
137	  if (mood === "idle" && Date.now() - lastMoveTs > SLEEP_AFTER_MS) {
138	    enterSleep();
139	  } else {
140	    wake();
141	    petRef?.clearRow();
142	  }
143	}
144	
145	async function handleDragRelease(vel: { vx: number; vy: number }): Promise<void> {
146	  const env = await fetchEnvironment();
147	  if (!env) return;
148	
149	  const cfg = loadConfig();
150	  if (cfg.mode === "climb" && env.windows.length > 0) {
151	    const surfaces = env.windows.map((w) => w.rect);
152	    await applyFall(vel.vx, env.workArea, surfaces, petRef, stop);
153	  } else {
154	    await applyThrow(vel.vx, vel.vy, env.workArea, petRef, stop);
155	  }
156	}
157	
158	async function loop(): Promise<void> {
159	  while (!stopRequested) {
160	    const active = await tick();
161	    await sleep(active ? TICK_MS : IDLE_TICK_MS);
162	  }
163	  petRef?.clearRow();
164	}
165	
166	export function initEngine(pet: Pet): void {
 75	/// Random walk within the work area. Walks to a target, idles, picks another.
 76	/// The target persists across ticks so the pet actually reaches it. Idling is
 77	/// done by setting `restUntil` (no blocking sleep) so the engine stays live.
 78	async function wander(ctx: ModeContext): Promise<Point> {
 79	  const { env, pos, pet } = ctx;
 80	  if (loadConfig().mode !== "wander") { wanderTarget = null; restUntil = 0; return pos; }
 81	  if (Date.now() < restUntil) return pos;
 82	  if (!wanderTarget || !inBounds(wanderTarget, env.workArea)) {
 83	    wanderTarget = randomTarget(env.workArea);
 84	  }
 85	  const target = wanderTarget;
 86	
 87	  const dx = target.x - pos.x;
 88	  const dy = target.y - pos.y;
 89	  const dist = Math.hypot(dx, dy);
 90	
 91	  if (dist < 6) {
 92	    wanderTarget = null;
 93	    restUntil = Date.now() + IDLE_MS_MIN + Math.random() * (IDLE_MS_MAX - IDLE_MS_MIN);
 94	    pet?.clearRow();
 95	    return pos;
 96	  }
 97	  return moveToward(target, pos, env.workArea, pet);
 98	}
 99	
100	/// Climb along the top edges of visible application windows, like Shimeji.
101	/// Walks horizontally until reaching the edge of a window, then either drops
102	/// to the next surface below or idles before reversing direction.
103	async function climb(ctx: ModeContext): Promise<Point> {
104	  const { env, pos, pet } = ctx;
105	  if (env.windows.length === 0) return wander(ctx);
106	  if (Date.now() < restUntil) return pos;
107	
108	  const surface = findSurfaceBelow(pos, env);
109	  if (!surface) return pos;
110	
111	  const dir = pickClimbDirection(pos, surface, env);
112	  const step = pxPerSec(loadConfig().speed) * DT_SEC;
113	  const nextX = pos.x + dir * step;
114	  const onEdge = nextX < surface.rect.left - 2 || nextX > surface.rect.right + 2;
115	
116	  if (onEdge) {
117	    restUntil = Date.now() + IDLE_MS_MIN + Math.random() * (IDLE_MS_MAX - IDLE_MS_MIN);
118	    pet?.clearRow();
119	    return pos;
120	  }
121	
122	  const next = clampToBounds(
123	    { x: nextX, y: surface.rect.top - WIN_H },
124	    env.workArea,
125	  );
126	  pet?.setRow(dir > 0 ? ROW_RIGHT : ROW_LEFT);
127	  return next;
128	}
129	
130	function moveToward(target: Point, pos: Point, bounds: Rect, pet: Pet | null): Point {
131	  const dx = target.x - pos.x;
132	  const dy = target.y - pos.y;
133	  const dist = Math.hypot(dx, dy);
134	  if (dist < 8) { pet?.clearRow(); return pos; }
135	  const speed = pxPerSec(loadConfig().speed);
136	  const move = Math.min(dist, speed * DT_SEC);
137	  const next = clampToBounds(
138	    { x: pos.x + (dx / dist) * move, y: pos.y + (dy / dist) * move },
139	    bounds,
140	  );
141	  pet?.setRow(dx > 0 ? ROW_RIGHT : ROW_LEFT);
142	  return next;
143	}
144	
145	function randomTarget(bounds: Rect): Point {
146	  const x = bounds.left + MARGIN + Math.random() * Math.max(1, bounds.right - bounds.left - WIN_W - MARGIN * 2);
147	  const y = bounds.top + MARGIN + Math.random() * Math.max(1, bounds.bottom - bounds.top - WIN_H - MARGIN * 2);
148	  return { x, y };
149	}
150	
151	interface SurfaceInfo { rect: Rect; isWindow: boolean }
152	
153	function findSurfaceBelow(pos: Point, env: Environment): SurfaceInfo | null {
154	  let best: SurfaceInfo | null = { rect: env.workArea, isWindow: false };
155	  let bestTop = env.workArea.bottom;
156	  const centerX = pos.x + WIN_W / 2;
157	  for (const w of env.windows) {
158	    if (centerX < w.rect.left || centerX > w.rect.right) continue;
159	    if (w.rect.top >= pos.y + WIN_H && w.rect.top < bestTop) {
160	      bestTop = w.rect.top;
161	      best = { rect: w.rect, isWindow: true };
162	    }
163	  }
164	  return best;
165	}
166	
167	function pickClimbDirection(pos: Point, surface: SurfaceInfo, _env: Environment): number {
168	  const center = pos.x + WIN_W / 2;
169	  const surfaceCenter = (surface.rect.left + surface.rect.right) / 2;
170	  if (Math.abs(center - surfaceCenter) < 10) return Math.random() < 0.5 ? -1 : 1;
171	  return center < surfaceCenter ? 1 : -1;
172	}

